def normalize_market_mode(market_mode: str | None = None) -> str:
    mode = str(market_mode or os.environ.get("EPM_MARKET_MODE", "spot")).strip().lower()
    if mode in {"perp", "perps", "future", "futures"}:
        return "perps"
    return "spot"


def _validate_policy_rows_in_trained_universe(
    df: pd.DataFrame,
    *,
    data_root: str | Path,
    run_id: str,
    source_path: Path,
) -> tuple[bool, Dict[str, Any]]:
    if "symbol" not in df.columns:
        return False, {
            "reason": "policy_oos_missing_symbol_column",
            "source_path": str(source_path),
        }
    try:
        trained = {
            str(sym)
            for sym in load_trained_symbol_universe(str(data_root), str(run_id))
            if str(sym)
        }
    except Exception as exc:
        return False, {
            "reason": "trained_universe_unavailable",
            "source_path": str(source_path),
            "error": str(exc),
        }
    if not trained:
        return False, {
            "reason": "trained_universe_empty",
            "source_path": str(source_path),
        }
    symbols = {str(sym) for sym in df["symbol"].dropna().astype(str)}
    outside = sorted(symbols - trained)
    return len(outside) == 0, {
        "reason": "ok" if not outside else "policy_oos_symbols_outside_trained_universe",
        "source_path": str(source_path),
        "rows": int(len(df)),
        "symbols": int(len(symbols)),
        "trained_universe_symbols": int(len(trained)),
        "outside_symbols": int(len(outside)),
        "outside_sample": outside[:20],
    }


def _env_flag(name: str, default: bool = True) -> bool:
    raw = os.environ.get(name)
    if raw is None:
        return bool(default)
    return str(raw).strip().lower() not in {"0", "false", "no", "off", ""}


def append_market_suffix(path: str, market_mode: str | None = None) -> str:
    norm = str(path).rstrip("/\\")
    if market_mode is None and norm.endswith(("_spot", "_perps", "_perp")):
        inferred_mode = "perps" if norm.endswith(("_perps", "_perp")) else "spot"
        mode = normalize_market_mode(inferred_mode)
    else:
        mode = normalize_market_mode(market_mode)
    for suffix in ("_spot", "_perps", "_perp"):
        if norm.endswith(suffix):
            return norm[: -len(suffix)] + f"_{mode}"
    return f"{norm}_{mode}"


