def _base_to_meta_top_frac() -> float:
    raw = os.environ.get("EPM_SIMPLE_POLICY_BASE_TO_META_TOP_FRAC")
    if raw is None or str(raw).strip() == "":
        return float(BASE_TO_META_TOP_FRAC)
    try:
        value = float(raw)
    except Exception:
        return float(BASE_TO_META_TOP_FRAC)
    return float(min(max(value, 0.01), 1.0))
