def _write_training_live_parity_contract(
    *,
    data_root: str,
    run_id: str,
    market_mode: str,
    strategy_ids: Sequence[str],
    deployment_payload: Dict[str, Any],
    portfolio_payload: Dict[str, Any],
) -> None:
    from extreme_price_movements.model_loader import load_full_state

    full_state = load_full_state(run_id, data_root)
    orchestrator = ModelOrchestrator(full_state, full_state)
    contract = build_training_live_parity_contract(
        data_root=data_root,
        run_id=run_id,
        market_mode=market_mode,
        orchestrator=orchestrator,
        model_bundle=full_state,
        strategy_ids=strategy_ids,
        deployment_payload=deployment_payload,
        portfolio_payload=portfolio_payload,
    )
    paths = persist_training_live_parity_contract(
        contract,
        data_root=data_root,
        run_id=run_id,
    )
    logger.info(
        "Saved training-live parity contract: %s",
        ", ".join(str(path) for path in paths),
    )


def _deployment_selected_strategy_ids(
    deployment_payload: Mapping[str, Any],
) -> List[str]:
    """Return the live-selected strategy IDs from a deployment payload."""
    ids: List[str] = []
    seen: Set[str] = set()
    for row in deployment_payload.get("strategies", []) or []:
        if not isinstance(row, Mapping) or row.get("selected") is False:
            continue
        sid = str(
            row.get("strategy_for_inference")
            or row.get("strategy_id")
            or row.get("canonical_strategy_id")
            or ""
        ).strip()
        if not sid or sid in seen:
            continue
        seen.add(sid)
        ids.append(sid)
    return sorted(ids)


def _refresh_deployment_reconciliation(
    deployment_payload: MutableMapping[str, Any],
) -> None:
    """Keep deployment reconciliation counts aligned after in-place filters."""
    selected = deployment_payload.get("strategies", []) or []
    rejected = deployment_payload.get("rejected_strategies", []) or []
    reconciliation = deployment_payload.setdefault("reconciliation", {})
    if not isinstance(reconciliation, MutableMapping):
        reconciliation = {}
        deployment_payload["reconciliation"] = reconciliation
    reconciliation["deployment_selected"] = len(selected)
    reconciliation["deployment_rejected"] = len(rejected)
    reconciliation["lgbm_mask_contract_covered"] = int(
        sum(
            1
            for row in selected
            if isinstance(row, Mapping) and row.get("lgbm_regime_mask")
        )
    )


def _assert_deployment_has_selected_strategies(
    deployment_payload: Mapping[str, Any],
    *,
    candidate_path: Path,
) -> None:
    selected = deployment_payload.get("strategies", []) or []
    if selected:
        return
    rejected = deployment_payload.get("rejected_strategies", []) or []
    reason_counts: Dict[str, int] = {}
    for row in rejected:
        if not isinstance(row, Mapping):
            continue
        reasons = row.get("reject_reasons") or []
        if not reasons and row.get("regime_mask_source") == "missing_lgbm_mask_contract":
            reasons = ["missing_lgbm_mask_contract"]
        for reason in reasons:
            reason_counts[str(reason)] = reason_counts.get(str(reason), 0) + 1
    raise RuntimeError(
        "No deployable strategies selected; refusing portfolio replay. "
        f"candidate_path={candidate_path} rejected={len(rejected)} "
        f"reasons={reason_counts}"
    )


def _filter_candidates_to_deployment_strategies(
    candidate_table: pd.DataFrame,
    strategy_ids: Sequence[str],
    deployment_payload: Optional[Mapping[str, Any]] = None,
) -> pd.DataFrame:
    if candidate_table.empty or not strategy_ids:
        return candidate_table.iloc[0:0].copy()
    selected = {str(strategy_id) for strategy_id in strategy_ids if str(strategy_id)}
    if not selected or "strategy_id" not in candidate_table.columns:
        return candidate_table.iloc[0:0].copy()
    mask = candidate_table["strategy_id"].astype(str).isin(selected)
    out = candidate_table.loc[mask].copy()
    if (
        out.empty
        or deployment_payload is None
        or "strategy_rank_pct" not in out.columns
    ):
        return out

    thresholds: Dict[str, float] = {}
    threshold_sources: Dict[str, str] = {}
    for row in deployment_payload.get("strategies", []) or []:
        if not isinstance(row, Mapping):
            continue
        sid = str(row.get("strategy_id") or "").strip()
        if not sid:
            continue
        threshold = _safe_float(row.get("deployment_rank_threshold"), np.nan)
        if np.isfinite(threshold):
            thresholds[sid] = float(threshold)
            threshold_sources[sid] = str(
                row.get("threshold_rank_score_source") or "policy_rank_pct"
            )
    if not thresholds:
        return out

    rank = pd.to_numeric(out["strategy_rank_pct"], errors="coerce")
    per_row_threshold = out["strategy_id"].astype(str).map(thresholds)
    threshold_mask = rank >= pd.to_numeric(per_row_threshold, errors="coerce")
    if "uncertainty_adjusted_ev_net_return" in out.columns:
        ev_adj = pd.to_numeric(
            out["uncertainty_adjusted_ev_net_return"], errors="coerce"
        )
        # Candidate rows without an uncertainty-EV fit are kept for backwards
        # compatibility; fitted rows must have positive adjusted net EV.
        threshold_mask &= ev_adj.isna() | (ev_adj > 0.0)
    out = out.loc[threshold_mask.fillna(False)].copy()
    if out.empty:
        return out
    strategy_values = out["strategy_id"].astype(str)
    out["base_strategy_threshold"] = pd.to_numeric(
        strategy_values.map(thresholds), errors="coerce"
    ).astype(np.float32)
    out["deployment_rank_threshold"] = out["base_strategy_threshold"]
    out["threshold_rank_score_source"] = strategy_values.map(threshold_sources).fillna(
        "policy_rank_pct"
    )
    return out


def _strategy_support_funnel_stage(
    strategy_id: str,
    stage: str,
    frame: Optional[pd.DataFrame],
) -> pd.DataFrame:
    """Summarise per-day strategy support at one policy/inference stage."""
    columns = [
        "strategy_id",
        "stage",
        "date",
        "rows",
        "symbols",
        "rank_max",
        "rank_mean",
        "score_max",
        "score_mean",
    ]
    if frame is None or frame.empty or "timestamp" not in frame.columns:
        return pd.DataFrame(columns=columns)
    ts = pd.to_datetime(frame["timestamp"], utc=True, errors="coerce")
    work = frame.loc[ts.notna()].copy()
    if work.empty:
        return pd.DataFrame(columns=columns)
    work["_support_date"] = ts.loc[work.index].dt.strftime("%Y-%m-%d")
    rank_col = next(
        (
            col
            for col in (
                "strategy_rank_pct",
                "policy_rank_pct",
                "rank_pct",
                "normalized_rank_score",
            )
            if col in work.columns
        ),
        None,
    )
    score_col = next(
        (col for col in ("calibrated_score", "clf", "oof_pred") if col in work.columns),
        None,
    )
    rows: List[Dict[str, Any]] = []
    for day, group in work.groupby("_support_date", sort=True):
        rank = (
            pd.to_numeric(group[rank_col], errors="coerce")
            if rank_col is not None
            else pd.Series(np.nan, index=group.index)
        )
        score = (
            pd.to_numeric(group[score_col], errors="coerce")
            if score_col is not None
            else pd.Series(np.nan, index=group.index)
        )
        rows.append(
            {
                "strategy_id": str(strategy_id),
                "stage": str(stage),
                "date": str(day),
                "rows": int(len(group)),
                "symbols": int(
                    group["symbol"].astype(str).nunique()
                    if "symbol" in group.columns
                    else 0
                ),
                "rank_max": _safe_float(rank.max(), np.nan),
                "rank_mean": _safe_float(rank.mean(), np.nan),
                "score_max": _safe_float(score.max(), np.nan),
                "score_mean": _safe_float(score.mean(), np.nan),
            }
        )
    return pd.DataFrame(rows, columns=columns)


def _write_strategy_support_funnel_report(
    stages: Sequence[pd.DataFrame],
    *,
    output_dir: Path,
    market_mode: str,
) -> Dict[str, Any]:
    non_empty = [stage for stage in stages if stage is not None and not stage.empty]
    if not non_empty:
        return {"enabled": True, "status": "empty", "rows": 0}
    output_dir.mkdir(parents=True, exist_ok=True)
    report = pd.concat(non_empty, ignore_index=True, sort=False)
    report = report.sort_values(["strategy_id", "date", "stage"]).reset_index(
        drop=True
    )
    csv_path = output_dir / "strategy_support_funnel_daily.csv"
    json_path = output_dir / "strategy_support_funnel_summary.json"
    report.to_csv(csv_path, index=False)
    latest = (
        report.sort_values(["strategy_id", "stage", "date"])
        .groupby(["strategy_id", "stage"], as_index=False)
        .tail(1)
        .sort_values(["strategy_id", "stage"])
    )
    summary = {
        "enabled": True,
        "status": "written",
        "rows": int(len(report)),
        "report_path": str(csv_path),
        "latest_by_strategy_stage": latest.to_dict(orient="records"),
    }
    _write_text_with_mode_alias(
        json_path,
        json.dumps(_json_safe(summary), indent=2),
        market_mode,
    )
    logger.info(
        "Saved strategy support funnel report to %s rows=%s",
        csv_path,
        len(report),
    )
    return summary


def _strategy_support_funnel_table_stages(
    stage: str,
    frame: Optional[pd.DataFrame],
) -> List[pd.DataFrame]:
    if frame is None or frame.empty or "strategy_id" not in frame.columns:
        return []
    stages: List[pd.DataFrame] = []
    for strategy_id, group in frame.groupby(frame["strategy_id"].astype(str)):
        stages.append(_strategy_support_funnel_stage(str(strategy_id), stage, group))
    return stages


def _apply_deployment_strategy_contract(
    payload: Dict[str, Any],
    strategy_ids: Sequence[str],
) -> Dict[str, Any]:
    """Narrow a live policy artifact contract to the deployed strategy set."""
    out = dict(payload or {})
    ids = sorted({str(sid).strip() for sid in strategy_ids if str(sid).strip()})
    cores = sorted({strategy_core_id(sid) for sid in ids})
    contract = dict(out.get("strategy_contract") or {})
    contract["strategy_ids"] = ids
    contract["strategy_cores"] = cores
    out["strategy_contract"] = contract
    return out


def run_simple_policy_optimisation(
    data_root: str,
    run_id: str,
    cost_pct: float = DEFAULT_POLICY_PER_SIDE_COST_PCT,
    max_strategies: Optional[int] = None,
    n_trials: Optional[int] = None,
    strategy_ids: Optional[Sequence[str]] = None,
    market_mode: Optional[str] = None,
    enable_regime_adaptor: Optional[bool] = None,
):
    market_mode = _normalise_market_mode(market_mode)
    if enable_regime_adaptor is None:
        enable_regime_adaptor = str(
            os.environ.get("EPM_SIMPLE_POLICY_REGIME_ADAPTOR", "0")
        ).strip().lower() not in {"0", "false", "no", "off"}
    data_root = _resolve_market_data_root(data_root, market_mode)
    artifacts_root = Path(data_root) / "artifacts"
    if run_id is None:
        candidates = [p for p in artifacts_root.iterdir() if p.is_dir()]
        if not candidates:
            logger.error(f"No artifact runs found under {artifacts_root}")
            return
        run_id = max(candidates, key=lambda p: p.stat().st_mtime).name
        logger.info(f"No run_id supplied; using latest artifact run {run_id}")
    run_root = Path(data_root) / "artifacts" / run_id
    output_run_root = _simple_policy_output_run_root(run_root)
    meta_oof_dir = run_root / "meta_oof"
    rank_reference_output_dir = (
        output_run_root / "simple_policy_optimiser" / "rank_reference"
    )
    policy_oos_dir = Path(
        os.environ.get(
            "EPM_SIMPLE_POLICY_OOS_PREDICTIONS_DIR",
            str(run_root / "policy_oos_predictions"),
        )
    )
    slice_plan_path = (
        run_root / "slices" / "slice_plan.json"
    )
    source_validation = _load_slice_plan_source_validation(slice_plan_path)
    runtime_exchange_context = _runtime_exchange_context(data_root, market_mode)
    slice_exchange_context = source_validation.get("exchange_context") or {}
    if slice_exchange_context != runtime_exchange_context:
        logger.error(
            "simple_policy_optimiser requires an exchange-scoped slice plan; "
            "refusing exchange mismatch runtime=%s slice_plan=%s path=%s",
            runtime_exchange_context,
            slice_exchange_context,
            slice_plan_path,
        )
        return
    if not bool(source_validation.get("oos_policy_slice_verified", False)):
        logger.warning(
            "Policy OOS source is not fully verifiable from slice_plan.json: %s",
            source_validation,
        )
    invalidate_auction_rank_reference(
        data_root=data_root,
        run_id=run_id,
        market_mode=market_mode,
        reason="simple_policy_optimiser_started_new_candidate_export",
        output_dir=rank_reference_output_dir,
    )
    stage_view, stage_name = _load_policy_stage_view(slice_plan_path)
    if stage_name != "policy_optimiser":
        logger.error(
            "simple_policy_optimiser requires stage_name='policy_optimiser'; "
            "refusing fallback stage=%s path=%s",
            stage_name,
            slice_plan_path,
        )
        return
    if not _stage_view_is_materialized(stage_view):
        logger.error(
            "Policy optimiser requires a materialized SlicePlanner policy view. "
            "stage=%s path=%s view=%s",
            stage_name,
            slice_plan_path,
            stage_view,
        )
        return

    meta_oof: Dict[str, pd.DataFrame] = {}
    meta_oof_sources: Dict[str, str] = {}
    source_contracts: Dict[str, Dict[str, Any]] = {}
    use_policy_oos_predictions = str(
        os.environ.get("EPM_SIMPLE_POLICY_USE_POLICY_OOS_PREDICTIONS", "1")
    ).strip().lower() in {"1", "true", "yes", "on"}
    use_precomputed_meta_oof = str(
        os.environ.get("EPM_SIMPLE_POLICY_USE_PRECOMPUTED_META_OOF", "0")
    ).strip().lower() in {"1", "true", "yes", "on"}
    env_strategy_ids = [
        s.strip()
        for s in str(os.environ.get("EPM_POLICY_STRATEGY_IDS", "")).split(",")
        if s.strip()
    ]
    strategy_ids_allowlist = _expand_strategy_id_allowlist(
        list(strategy_ids or []) + env_strategy_ids
    )

    if use_policy_oos_predictions and policy_oos_dir.exists():
        policy_oos_paths = sorted(policy_oos_dir.glob("policy_oos_*_clf.parquet"))
        if not policy_oos_paths:
            policy_oos_paths = sorted(policy_oos_dir.glob("policy_oos_*.parquet"))
        for pq_file in policy_oos_paths:
            strategy_id = pq_file.stem.replace("policy_oos_", "")
            if strategy_id.endswith("_tbm_clf"):
                strategy_id = strategy_id[: -len("_tbm_clf")]
            elif strategy_id.endswith("_clf"):
                strategy_id = strategy_id[: -len("_clf")]
            if strategy_id.endswith("_correctness"):
                strategy_id = strategy_id[: -len("_correctness")]
            if not _strategy_id_matches_allowlist(strategy_id, strategy_ids_allowlist):
                continue
            if strategy_id in meta_oof:
                continue
            df = pd.read_parquet(pq_file)
            valid_source, contract = _validate_policy_prediction_oos_contract(
                df,
                source_validation=source_validation,
                source_path=pq_file,
            )
            source_contracts[strategy_id] = contract
            if not valid_source:
                logger.error(
                    "Refusing policy-OOS prediction source %s for %s: %s",
                    pq_file,
                    strategy_id,
                    contract,
                )
                continue
            df = _filter_rows_to_stage_view(df, stage_view)
            if df.empty:
                logger.info(
                    "Policy-OOS predictions %s have no rows in policy slice %s.",
                    pq_file,
                    stage_name,
                )
                continue
            df = _filter_policy_quote_rows(df, market_mode)
            if df.empty:
                logger.info(
                    "Policy-OOS predictions %s have no rows after policy quote filter %s.",
                    pq_file,
                    _policy_quote_filter(market_mode) or "<none>",
                )
                continue
            universe_ok, universe_contract = _validate_policy_rows_in_trained_universe(
                df,
                data_root=data_root,
                run_id=run_id,
                source_path=pq_file,
            )
            source_contracts[strategy_id]["trained_universe_contract"] = universe_contract
            if not universe_ok:
                if (
                    universe_contract.get("reason")
                    == "policy_oos_symbols_outside_trained_universe"
                ):
                    trained_symbols = {
                        str(sym)
                        for sym in load_trained_symbol_universe(
                            str(data_root), str(run_id)
                        )
                        if str(sym)
                    }
                    before_universe_filter = int(len(df))
                    df = df.loc[df["symbol"].astype(str).isin(trained_symbols)].copy()
                    universe_contract["rows_before_trained_universe_filter"] = (
                        before_universe_filter
                    )
                    universe_contract["rows_after_trained_universe_filter"] = int(
                        len(df)
                    )
                    source_contracts[strategy_id][
                        "trained_universe_contract"
                    ] = universe_contract
                    logger.warning(
                        "Filtered policy-OOS prediction source %s for %s to "
                        "trained universe: %s",
                        pq_file,
                        strategy_id,
                        universe_contract,
                    )
                    if df.empty:
                        logger.error(
                            "Refusing policy-OOS prediction source %s for %s: "
                            "no rows remain after trained-universe filter",
                            pq_file,
                            strategy_id,
                        )
                        continue
                else:
                    logger.error(
                        "Refusing policy-OOS prediction source %s for %s: %s",
                        pq_file,
                        strategy_id,
                        universe_contract,
                    )
                    continue
            df = _ensure_regime_prediction_context(
                df,
                data_root=data_root,
                run_id=run_id,
                strategy_id=strategy_id,
                stage_view=stage_view,
            )
            meta_oof[strategy_id] = df
            meta_oof_sources[strategy_id] = str(pq_file)
            if max_strategies is not None and len(meta_oof) >= int(max_strategies):
                break

    if (
        not meta_oof
        and use_precomputed_meta_oof
        and meta_oof_dir.exists()
        and _allow_meta_oof_policy_source()
    ):
        precomputed_paths = sorted(meta_oof_dir.glob("meta_oof_*_clf.parquet"))
        route_paths_by_strategy: Dict[str, List[Path]] = {}
        for route_path in precomputed_paths:
            route = mr_tf_route_from_path(route_path)
            if route in {"mr", "tf"}:
                route_sid = _meta_oof_strategy_id_from_path(route_path)
                if route_sid:
                    route_paths_by_strategy.setdefault(route_sid, []).append(route_path)
        for pq_file in precomputed_paths:
            if mr_tf_route_from_path(pq_file) in {"mr", "tf"}:
                continue
            strategy_id = _meta_oof_strategy_id_from_path(pq_file)
            if not _strategy_id_matches_allowlist(strategy_id, strategy_ids_allowlist):
                continue
            if strategy_id in meta_oof:
                continue
            df = pd.read_parquet(pq_file)
            df = _filter_rows_to_stage_view(df, stage_view)
            if df.empty:
                logger.info(
                    "Precomputed meta OOF %s has no rows in policy slice %s.",
                    pq_file,
                    stage_name,
                )
                continue
            df = _filter_policy_quote_rows(df, market_mode)
            if df.empty:
                logger.info(
                    "Precomputed meta OOF %s has no rows after policy quote filter %s.",
                    pq_file,
                    _policy_quote_filter(market_mode) or "<none>",
                )
                continue
            df, route_overlay = _overlay_meta_oof_route_paths(
                df,
                route_paths_by_strategy.get(strategy_id, []),
                market_mode=market_mode,
                stage_view=stage_view,
            )
            if route_overlay:
                logger.info(
                    "[%s] Applied MR/TF precomputed meta-OOF overlays: %s",
                    strategy_id,
                    route_overlay,
                )
            df = _ensure_regime_prediction_context(
                df,
                data_root=data_root,
                run_id=run_id,
                strategy_id=strategy_id,
                stage_view=stage_view,
            )
            meta_oof[strategy_id] = df
            meta_oof_sources[strategy_id] = str(pq_file)
            if max_strategies is not None and len(meta_oof) >= int(max_strategies):
                break
    elif use_precomputed_meta_oof and not _allow_meta_oof_policy_source():
        logger.error(
            "Refusing EPM_SIMPLE_POLICY_USE_PRECOMPUTED_META_OOF for policy-OOS "
            "optimisation. meta_oof is training-window OOF, not policy-OOS. Set "
            "EPM_SIMPLE_POLICY_ALLOW_META_OOF_POLICY_SOURCE=1 only for diagnostics."
        )

    if not meta_oof:
        if not _allow_final_fit_policy_generation():
            logger.error(
                "No verified policy-OOS prediction parquet was found under %s. "
                "Refusing final-fit model generation for policy OOS metrics because "
                "those models may have seen the policy slice. Generate "
                "artifacts/%s/policy_oos_predictions/policy_oos_<strategy>_clf.parquet "
                "with train_end < prediction_start, or set "
                "EPM_SIMPLE_POLICY_ALLOW_FINAL_FIT_POLICY_GENERATION=1 only for "
                "diagnostic score dumps.",
                policy_oos_dir,
                run_id,
            )
            return
        logger.info(
            "Generating diagnostic policy-slice predictions from final full-fit "
            "inference models for stage %s.",
            stage_name,
        )
        meta_oof, meta_oof_sources = _generate_policy_predictions_from_models(
            data_root=data_root,
            run_id=run_id,
            stage_view=stage_view,
            max_strategies=max_strategies,
            strategy_ids_allowlist=(
                strategy_ids_allowlist if strategy_ids_allowlist else None
            ),
            market_mode=market_mode,
            source_tag="generated_from_train_meta_state",
        )
        if not meta_oof:
            logger.error(
                "No policy-slice predictions available after model generation fallback."
            )
            return
        meta_oof = {
            sid: _ensure_regime_prediction_context(
                _filter_policy_quote_rows(frame, market_mode),
                data_root=data_root,
                run_id=run_id,
                strategy_id=sid,
                stage_view=stage_view,
            )
            for sid, frame in meta_oof.items()
            if not _filter_policy_quote_rows(frame, market_mode).empty
        }
    elif strategy_ids_allowlist:
        missing_strategy_ids = {
            sid
            for sid in set(strategy_ids_allowlist)
            if not any(
                _strategy_id_matches_allowlist(existing_sid, {sid})
                for existing_sid in meta_oof.keys()
            )
        }
        if missing_strategy_ids:
            logger.warning(
                "Verified policy-OOS predictions are missing %s allowlisted "
                "strategy ids; generating missing diagnostic policy-slice "
                "predictions from inference models.",
                len(missing_strategy_ids),
            )
            if not _allow_final_fit_policy_generation():
                logger.error(
                    "Refusing final-fit generation for missing policy-OOS "
                    "strategies: %s",
                    sorted(missing_strategy_ids),
                )
                return
            generated_oof, generated_sources = _generate_policy_predictions_from_models(
                data_root=data_root,
                run_id=run_id,
                stage_view=stage_view,
                max_strategies=None,
                strategy_ids_allowlist=missing_strategy_ids,
                market_mode=market_mode,
                source_tag="generated_from_train_meta_state",
            )
            for sid, frame in generated_oof.items():
                if sid in meta_oof:
                    continue
                filtered = _filter_policy_quote_rows(frame, market_mode)
                if filtered.empty:
                    continue
                meta_oof[sid] = _ensure_regime_prediction_context(
                    filtered,
                    data_root=data_root,
                    run_id=run_id,
                    strategy_id=sid,
                    stage_view=stage_view,
                )
                meta_oof_sources[sid] = generated_sources.get(sid, "model_generation")

    n_trials = int(
        n_trials
        if n_trials is not None
        else os.environ.get("SIMPLE_POLICY_N_TRIALS", DEFAULT_N_TRIALS)
    )
    n_trials = max(1, n_trials)

    from extreme_price_movements.inference.parity import calibrated_score_and_threshold
    from extreme_price_movements.simple_position_sizer import load_calibration_curves

    ds = _make_policy_replay_store(data_root, market_mode)
    calibration_data = load_calibration_curves(data_root, run_id)
    prediction_source_summary = _summarize_policy_prediction_sources(
        meta_oof.keys(), meta_oof_sources
    )

    results_json = {}
    strategy_top5_daily_weekly: list[dict[str, Any]] = []
    simple_policy_candidate_frames: List[pd.DataFrame] = []
    strategy_support_funnel_frames: List[pd.DataFrame] = []
    recent_oof_asset_report_frames: List[pd.DataFrame] = []
    recent_oof_asset_summaries: List[Dict[str, Any]] = []
    oos_results_json = {
        "generated_by": "simple_policy_optimiser",
        "market_mode": market_mode,
        "run_id": run_id,
        "rank_threshold": None,
        "rank_slice": "full_policy_oos_for_threshold_discovery",
        "reporting_rank_threshold": REPORTING_POLICY_RANK_THRESHOLD,
        "reporting_rank_slice": REPORTING_POLICY_LABEL,
        "cost_pct": cost_pct,
        "split": (
            "recent_policy_optimisation_last_8w_with_outer_validation_9_13w_ago_"
            "then_stage_b_3fold_cv"
        ),
        "cv_folds": DEFAULT_CV_FOLDS,
        "n_trials_per_fit": n_trials,
        "prediction_source": {
            **prediction_source_summary,
            "slice_plan_path": str(slice_plan_path),
            "policy_oos_predictions_dir": str(policy_oos_dir),
            "source_contracts": source_contracts,
            **source_validation,
            "not_model_refit": True,
            "requested_policy_oos_predictions": bool(use_policy_oos_predictions),
            "requested_precomputed_meta_oof": bool(use_precomputed_meta_oof),
        },
        "strategies": {},
    }

    for strategy_id, df in meta_oof.items():
        logger.info(f"Optimising strategy: {strategy_id}")

        if "clf" not in df.columns and "oof_p_tp" in df.columns:
            df["clf"] = df["oof_p_tp"]
        elif "clf" not in df.columns and "oof_pred" in df.columns:
            df["clf"] = df["oof_pred"]

        if "clf" not in df.columns:
            logger.warning(
                f"Strategy {strategy_id} has no valid clf or oof_p_tp score. Skipping."
            )
            continue

        df["raw_meta_prediction"] = pd.to_numeric(df["clf"], errors="coerce")
        df["calibrated_score"] = df["raw_meta_prediction"].map(
            lambda raw_score: (
                calibrated_score_and_threshold(
                    raw_score=float(raw_score),
                    strategy_id=strategy_id,
                    calibration_data=calibration_data,
                    default_threshold=1.0,
                )[0]
                if pd.notna(raw_score)
                else np.nan
            )
        )
        df["rank_pct"] = df["calibrated_score"].rank(method="max", pct=True)
        df["strategy_id"] = strategy_id
        strategy_support_funnel_frames.append(
            _strategy_support_funnel_stage(strategy_id, "meta_prediction_rows", df)
        )

        if "side" not in df.columns:
            if strategy_id.startswith("short"):
                df["side"] = -1
            else:
                df["side"] = 1

        # Stage A is diagnostic: it describes how the simple TP/SL proxy behaves
        # across ranks, but it is deliberately not the source of truth for
        # deployability. Stage B receives a broad rank floor and tests optimized
        # exits on that wider candidate set.
        df_policy_all = df.dropna(
            subset=["timestamp", "symbol", "rank_pct", "calibrated_score"]
        ).copy()
        df_policy_all["market_mode"] = market_mode
        if "timestamp" in df_policy_all.columns:
            df_policy_all = df_policy_all.sort_values("timestamp").reset_index(
                drop=True
            )
        else:
            df_policy_all = df_policy_all.sort_index().reset_index(drop=True)

        n_policy = len(df_policy_all)
        strategy_support_funnel_frames.append(
            _strategy_support_funnel_stage(strategy_id, "policy_clean_rows", df_policy_all)
        )
        if n_policy < 10:
            continue
        opt_mask_all, validation_mask_all, policy_outer_split = (
            _policy_optimisation_validation_masks(df_policy_all, stage_view)
        )
        if int(opt_mask_all.sum()) < 10:
            logger.warning(
                "[%s] Recent policy optimisation split has only %s optimisation "
                "rows from %s policy rows. Skipping.",
                strategy_id,
                int(opt_mask_all.sum()),
                n_policy,
            )
            continue
        if policy_outer_split.get("using_recent_policy_outer_split"):
            df_policy_all["rank_pct"] = _rank_pct_against_reference(
                df_policy_all["calibrated_score"],
                df_policy_all.loc[opt_mask_all, "calibrated_score"],
            )
            df_policy_all = df_policy_all.dropna(
                subset=["rank_pct", "calibrated_score"]
            ).copy()
            opt_mask_all, validation_mask_all, policy_outer_split = (
                _policy_optimisation_validation_masks(df_policy_all, stage_view)
            )
        opt_indices_all = np.flatnonzero(opt_mask_all.to_numpy(dtype=bool))
        validation_indices_all = np.flatnonzero(
            validation_mask_all.to_numpy(dtype=bool)
        )
        df_policy_fit = df_policy_all.iloc[opt_indices_all].copy().reset_index(
            drop=True
        )
        df_policy_outer_validation = df_policy_all.iloc[
            validation_indices_all
        ].copy().reset_index(drop=True)
        strategy_support_funnel_frames.append(
            _strategy_support_funnel_stage(strategy_id, "policy_fit_window_rows", df_policy_fit)
        )
        logger.info(
            "[%s] Policy outer split: optimisation_rows=%s validation_rows=%s "
            "recent_split=%s",
            strategy_id,
            len(df_policy_fit),
            len(df_policy_outer_validation),
            bool(policy_outer_split.get("using_recent_policy_outer_split")),
        )

        policy_generation_source = str(
            meta_oof_sources.get(strategy_id) or "generated_from_train_meta_state:unknown"
        )
        if "policy_oos_generation_source" not in df_policy_all.columns:
            df_policy_all["policy_oos_generation_source"] = policy_generation_source
        if "policy_oos_source_model_fit_end" not in df_policy_all.columns:
            source_contract = source_contracts.get(strategy_id) or {}
            df_policy_all["policy_oos_source_model_fit_end"] = str(
                source_contract.get("source_model_fit_end")
                or source_contract.get("fit_end")
                or "slicer_planner_row_disjoint_policy_slice"
            )

        try:
            ref_path = persist_policy_rank_reference(
                df_policy_fit,
                data_root=data_root,
                run_id=run_id,
                strategy_id=strategy_id,
                market_mode=market_mode,
                output_dir=rank_reference_output_dir,
            )
            logger.info(
                "[%s] Persisted policy rank reference: path=%s rows=%s",
                strategy_id,
                ref_path,
                len(df_policy_fit),
            )
        except Exception as exc:
            logger.error(
                "[%s] Failed to persist policy rank reference; skipping strategy "
                "to avoid non-reproducible live rank thresholds: %s",
                strategy_id,
                exc,
            )
            continue

        t_paths = time.perf_counter()
        all_policy_paths = _fetch_policy_paths(df_policy_all, ds)
        df_policy_all, all_policy_paths = _apply_delayed_entry_execution_model(
            df_policy_all,
            all_policy_paths,
            data_root=data_root,
            market_mode=market_mode,
        )
        df_policy_fit = df_policy_all.iloc[opt_indices_all].copy().reset_index(
            drop=True
        )
        df_policy_outer_validation = df_policy_all.iloc[
            validation_indices_all
        ].copy().reset_index(drop=True)
        strategy_support_funnel_frames.append(
            _strategy_support_funnel_stage(
                strategy_id,
                "policy_fit_after_entry_model_rows",
                df_policy_fit,
            )
        )
        opt_policy_paths = _path_take(all_policy_paths, opt_indices_all)
        validation_policy_paths = _path_take(all_policy_paths, validation_indices_all)
        finite_path_rows, total_path_rows, path_coverage = _assert_policy_path_coverage(
            strategy_id=strategy_id,
            paths=all_policy_paths,
        )
        logger.info(
            "[%s] Policy path matrix built: rows=%s shape=%s finite_entries=%s "
            "finite_path_rows=%s coverage=%.2f%% delayed_1m_entries=%s elapsed=%.1fs",
            strategy_id,
            len(df_policy_all),
            tuple(all_policy_paths[0].shape),
            int(np.isfinite(all_policy_paths[0][:, 0]).sum()),
            int(finite_path_rows),
            100.0 * float(path_coverage),
            int(
                (
                    df_policy_all.get("entry_execution_source", pd.Series(dtype=object))
                    == "delayed_1m_intraminute_proxy"
                ).sum()
            ),
            time.perf_counter() - t_paths,
        )
        stage_a_round_trip_cost_pct = float(SIMPLE_DISCOVERY_ROUND_TRIP_COST_PCT)
        stage_a_cost_pct = stage_a_round_trip_cost_pct / 2.0
        t_stage_a = time.perf_counter()
        deployment_threshold_metrics = discover_deployment_rank_threshold_simple_grid(
            df_policy_fit,
            opt_policy_paths,
            cost_pct=stage_a_cost_pct,
            timestamp_col="timestamp",
            symbol_col="symbol",
            side_col="side",
            strategy_col="strategy_id",
            max_concurrent_per_asset=DEPLOYMENT_MAX_CONCURRENT_PER_ASSET,
            lo=DEPLOYMENT_THRESHOLD_MIN,
            hi=DEPLOYMENT_THRESHOLD_MAX,
            precision=DEPLOYMENT_THRESHOLD_PRECISION,
        )
        logger.info(
            "[%s] Stage A threshold discovery completed: elapsed=%.1fs n_trades=%s mean_net=%.6f",
            strategy_id,
            time.perf_counter() - t_stage_a,
            int(deployment_threshold_metrics.get("n_trades", 0) or 0),
            _safe_float(deployment_threshold_metrics.get("mean_net_trade"), np.nan),
        )
        raw_deployment_rank_threshold = float(
            deployment_threshold_metrics.get("deployment_rank_threshold", 1.0)
        )
        stage_a_diagnostic_rank_threshold = float(
            np.clip(
                raw_deployment_rank_threshold
                + DEPLOYMENT_RANK_THRESHOLD_EXTRA_REQUIREMENT,
                DEPLOYMENT_THRESHOLD_MIN,
                DEPLOYMENT_THRESHOLD_MAX,
            )
        )
        deployment_rank_threshold = float(
            np.clip(
                DEPLOYMENT_STAGE_B_CANDIDATE_RANK_FLOOR,
                DEPLOYMENT_THRESHOLD_MIN,
                DEPLOYMENT_THRESHOLD_MAX,
            )
        )
        deployment_threshold_metrics["raw_deployment_rank_threshold"] = float(
            raw_deployment_rank_threshold
        )
        deployment_threshold_metrics["stage_a_diagnostic_rank_threshold"] = float(
            stage_a_diagnostic_rank_threshold
        )
        deployment_threshold_metrics["stage_a_role"] = "diagnostic_only"
        deployment_threshold_metrics["stage_b_candidate_rank_floor"] = float(
            deployment_rank_threshold
        )
        deployment_threshold_metrics["deployment_rank_threshold"] = float(
            deployment_rank_threshold
        )
        deployment_threshold_metrics["deployment_rank_extra_requirement"] = float(
            DEPLOYMENT_RANK_THRESHOLD_EXTRA_REQUIREMENT
        )
        trade_idx = np.flatnonzero(
            df_policy_fit["rank_pct"].to_numpy(dtype=np.float32)
            >= deployment_rank_threshold
        )
        df_top = df_policy_fit.iloc[trade_idx].copy().reset_index(drop=True)
        strategy_support_funnel_frames.append(
            _strategy_support_funnel_stage(strategy_id, "stage_b_rank_floor_rows", df_top)
        )
        all_paths = _path_take(opt_policy_paths, trade_idx)
        stage_a0_ev_prefilter = _fit_simple_rank_net_ev_prefilter(
            df_top,
            all_paths,
            cost_pct=stage_a_cost_pct,
            market_mode=market_mode,
        )
        df_top, stage_a0_keep_mask, stage_a0_apply_summary = (
            _apply_simple_rank_net_ev_prefilter(
                df_top,
                stage_a0_ev_prefilter,
                cost_pct=stage_a_cost_pct,
                market_mode=market_mode,
                context="stage_b_fit",
            )
        )
        strategy_support_funnel_frames.append(
            _strategy_support_funnel_stage(
                strategy_id,
                "stage_b_after_simple_net_ev_prefilter",
                df_top,
            )
        )
        if len(stage_a0_keep_mask) == len(trade_idx):
            stage_a0_keep_idx = np.flatnonzero(stage_a0_keep_mask)
            trade_idx = trade_idx[stage_a0_keep_idx]
            all_paths = _path_take(all_paths, stage_a0_keep_idx)
        deployment_threshold_metrics["simple_net_ev_prefilter"] = {
            "fit": stage_a0_ev_prefilter,
            "stage_b_fit": stage_a0_apply_summary,
        }
        n = len(df_top)
        logger.info(
            "[%s] Stage A diagnostic selected raw_rank>=%.4f; "
            "diagnostic_rank_after_extra=%.4f extra_requirement=%.4f. "
            "Stage B broad candidate_floor_rank>=%.4f from %s full policy rows "
            "-> %s Stage B optimisation rows. simple net-EV prefilter "
            "binding=%s diagnostic_keep=%s/%s. simple_sl=%.2f simple_tp=%.2f "
            "mean_net_trade=%.6f n_trades=%s stage_a_round_trip_cost=%.4f",
            strategy_id,
            raw_deployment_rank_threshold,
            stage_a_diagnostic_rank_threshold,
            DEPLOYMENT_RANK_THRESHOLD_EXTRA_REQUIREMENT,
            deployment_rank_threshold,
            len(df_policy_fit),
            n,
            bool(stage_a0_apply_summary.get("binding", False)),
            int(stage_a0_apply_summary.get("diagnostic_rows_after", n) or 0),
            int(stage_a0_apply_summary.get("rows_before", n) or 0),
            _safe_float(deployment_threshold_metrics.get("simple_sl_mult"), np.nan),
            _safe_float(deployment_threshold_metrics.get("simple_tp_mult"), np.nan),
            _safe_float(deployment_threshold_metrics.get("mean_net_trade"), np.nan),
            int(deployment_threshold_metrics.get("n_trades", 0) or 0),
            stage_a_round_trip_cost_pct,
        )
        if n < SIMPLE_NET_EV_PREFILTER_MIN_STAGE_B_ROWS:
            logger.warning(
                "[%s] Stage B broad floor rank>=%.4f left only %s rows "
                "(minimum=%s). Skipping.",
                strategy_id,
                deployment_rank_threshold,
                n,
                SIMPLE_NET_EV_PREFILTER_MIN_STAGE_B_ROWS,
            )
            continue

        folds = _build_equal_time_folds(n, DEFAULT_CV_FOLDS)
        if len(folds) != DEFAULT_CV_FOLDS:
            logger.warning(
                "[%s] Expected %s CV folds, got %s. Skipping.",
                strategy_id,
                DEFAULT_CV_FOLDS,
                len(folds),
            )
            continue

        logger.info(
            "[%s] Running %s-fold chronological CV on %s Stage B policy rows; fold sizes=%s",
            strategy_id,
            DEFAULT_CV_FOLDS,
            n,
            [int(len(fold)) for fold in folds],
        )

        fold_results: List[Dict[str, Any]] = []
        fold_val_metrics: List[Dict[str, Any]] = []
        all_idx = np.arange(n, dtype=np.int64)
        for fold_no, val_idx in enumerate(folds, start=1):
            train_idx = np.setdiff1d(all_idx, val_idx, assume_unique=True)
            df_train = df_top.iloc[train_idx].copy().reset_index(drop=True)
            df_val = df_top.iloc[val_idx].copy().reset_index(drop=True)
            train_paths = _path_take(all_paths, train_idx)
            val_paths = _path_take(all_paths, val_idx)

            best_params, best_size_power, _, fit_summary = _optimise_policy_on_rows(
                df_train,
                train_paths,
                cost_pct=cost_pct,
                n_trials=n_trials,
            )
            train_metrics = _evaluate_policy_subsets(
                strategy_id,
                f"cv_fold_{fold_no}_train",
                df_train,
                train_paths,
                cost_pct=cost_pct,
                best_params=best_params,
                best_size_power=best_size_power,
            )
            val_metrics = _evaluate_policy_subsets(
                strategy_id,
                f"cv_fold_{fold_no}_validation",
                df_val,
                val_paths,
                cost_pct=cost_pct,
                best_params=best_params,
                best_size_power=best_size_power,
            )
            fold_val_metrics.append(val_metrics)
            logger.info(
                "[%s] CV fold %s/%s best_params=%s best_size_power=%.3f "
                "train_top5_avg=%.6f val_top5_avg=%.6f",
                strategy_id,
                fold_no,
                DEFAULT_CV_FOLDS,
                best_params,
                best_size_power,
                float(train_metrics.get("top_5", {}).get("avg_pnl_bankroll", np.nan)),
                float(val_metrics.get("top_5", {}).get("avg_pnl_bankroll", np.nan)),
            )
            train_top5 = train_metrics.get("top_5", {})
            val_top5 = val_metrics.get("top_5", {})
            train_validation_gap = {
                "avg_net_pnl_per_trade": float(
                    train_top5.get("avg_pnl_bankroll", np.nan)
                )
                - float(val_top5.get("avg_pnl_bankroll", np.nan)),
                "win_rate": float(train_top5.get("hit_rate", np.nan))
                - float(val_top5.get("hit_rate", np.nan)),
                "sortino": float(train_top5.get("m_sortino", np.nan))
                - float(val_top5.get("m_sortino", np.nan)),
                "max_drawdown": float(train_top5.get("max_drawdown", np.nan))
                - float(val_top5.get("max_drawdown", np.nan)),
            }
            logger.info(
                "[%s] CV fold %s train-validation gap top5: "
                "avg_net=%.6f win_rate=%.4f sortino=%.4f maxdd=%.6f",
                strategy_id,
                fold_no,
                train_validation_gap["avg_net_pnl_per_trade"],
                train_validation_gap["win_rate"],
                train_validation_gap["sortino"],
                train_validation_gap["max_drawdown"],
            )
            fold_results.append(
                {
                    "fold": fold_no,
                    "train_rows_stage_b": int(len(df_train)),
                    "validation_rows_stage_b": int(len(df_val)),
                    "deployment_rank_threshold": float(deployment_rank_threshold),
                    "best_params": best_params,
                    "best_size_power": float(best_size_power),
                    "fit_summary": fit_summary,
                    "train_metrics": train_metrics,
                    "validation_metrics": val_metrics,
                    "train_validation_gap_top5": train_validation_gap,
                }
            )

        validation_metrics_average = _average_validation_metrics(fold_val_metrics)
        logger.info(
            "[%s] CV validation average top5 avg_pnl_bankroll=%.6f n_trades=%.1f",
            strategy_id,
            float(
                validation_metrics_average.get("top_5", {}).get(
                    "avg_pnl_bankroll", np.nan
                )
            ),
            float(validation_metrics_average.get("top_5", {}).get("n_trades", np.nan)),
        )

        final_params, final_size_power, _, final_fit_summary = _optimise_policy_on_rows(
            df_top,
            all_paths,
            cost_pct=cost_pct,
            n_trials=n_trials,
        )
        final_fit_metrics = _evaluate_policy_subsets(
            strategy_id,
            "final_fit_all_policy_rows",
            df_top,
            all_paths,
            cost_pct=cost_pct,
            best_params=final_params,
            best_size_power=final_size_power,
        )
        deployment_sim_metrics = simulate_and_score(
            df_top.copy(),
            all_paths[0],
            all_paths[1],
            all_paths[2],
            all_paths[3],
            cost_pct=cost_pct,
            size_power=final_size_power,
            max_concurrent_trades=MAX_CONCURRENT_TRADES,
            max_concurrent_per_asset=DEPLOYMENT_MAX_CONCURRENT_PER_ASSET,
            **_without_concurrency_param(final_params),
        )
        final_policy_threshold_rows = _build_deployment_threshold_rows(
            df_top,
            all_paths,
            cost_pct=cost_pct,
            best_params=final_params,
            best_size_power=final_size_power,
            metrics=deployment_sim_metrics,
        )
        policy_drift_risk_fit, policy_drift_risk_fit_summary = (
            _fit_simple_policy_calibrated_drift_risk(final_policy_threshold_rows)
        )
        final_policy_threshold_rows, final_policy_drift_risk_apply = (
            _apply_simple_policy_calibrated_drift_risk(
                final_policy_threshold_rows,
                policy_drift_risk_fit,
                context="final_policy_fit_rows",
            )
        )
        final_policy_deployment_metrics = score_deployment_threshold_rows(
            final_policy_threshold_rows
        )
        final_policy_deployment_metrics["calibrated_drift_risk"] = {
            "fit": policy_drift_risk_fit_summary,
            "application": final_policy_drift_risk_apply,
        }
        outer_validation_metrics: Dict[str, Any] = {"status": "not_available"}
        outer_validation_deployment_metrics: Dict[str, Any] = {"status": "not_available"}
        if not df_policy_outer_validation.empty:
            validation_trade_idx = np.flatnonzero(
                df_policy_outer_validation["rank_pct"].to_numpy(dtype=np.float32)
                >= deployment_rank_threshold
            )
            if validation_trade_idx.size:
                df_validation_top = (
                    df_policy_outer_validation.iloc[validation_trade_idx]
                    .copy()
                    .reset_index(drop=True)
                )
                validation_top_paths = _path_take(
                    validation_policy_paths, validation_trade_idx
                )
                df_validation_top, validation_ev_keep_mask, validation_ev_summary = (
                    _apply_simple_rank_net_ev_prefilter(
                        df_validation_top,
                        stage_a0_ev_prefilter,
                        cost_pct=stage_a_cost_pct,
                        market_mode=market_mode,
                        context="outer_validation",
                    )
                )
                if len(validation_ev_keep_mask) == len(validation_trade_idx):
                    validation_keep_idx = np.flatnonzero(validation_ev_keep_mask)
                    validation_top_paths = _path_take(
                        validation_top_paths,
                        validation_keep_idx,
                    )
                outer_validation_deployment_metrics[
                    "simple_net_ev_prefilter"
                ] = validation_ev_summary
                if df_validation_top.empty:
                    outer_validation_metrics = {
                        "status": "no_rows_after_simple_net_ev_prefilter",
                        "validation_rows": int(len(df_policy_outer_validation)),
                        "deployment_rank_threshold": float(deployment_rank_threshold),
                        "simple_net_ev_prefilter": validation_ev_summary,
                    }
                else:
                    outer_validation_metrics = _evaluate_policy_subsets(
                        strategy_id,
                        "outer_recent_policy_validation",
                        df_validation_top,
                        validation_top_paths,
                        cost_pct=cost_pct,
                        best_params=final_params,
                        best_size_power=final_size_power,
                    )
                    outer_validation_metrics[
                        "simple_net_ev_prefilter"
                    ] = validation_ev_summary
                    outer_validation_sim_metrics = simulate_and_score(
                        df_validation_top.copy(),
                        validation_top_paths[0],
                        validation_top_paths[1],
                        validation_top_paths[2],
                        validation_top_paths[3],
                        cost_pct=cost_pct,
                        size_power=final_size_power,
                        max_concurrent_trades=MAX_CONCURRENT_TRADES,
                        max_concurrent_per_asset=DEPLOYMENT_MAX_CONCURRENT_PER_ASSET,
                        **_without_concurrency_param(final_params),
                    )
                    outer_validation_rows = _build_deployment_threshold_rows(
                        df_validation_top,
                        validation_top_paths,
                        cost_pct=cost_pct,
                        best_params=final_params,
                        best_size_power=final_size_power,
                        metrics=outer_validation_sim_metrics,
                    )
                    outer_validation_rows, outer_risk_apply = (
                        _apply_simple_policy_calibrated_drift_risk(
                            outer_validation_rows,
                            policy_drift_risk_fit,
                            context="outer_policy_validation",
                        )
                    )
                    outer_validation_deployment_metrics = score_deployment_threshold_rows(
                        outer_validation_rows
                    )
                    outer_validation_deployment_metrics[
                        "simple_net_ev_prefilter"
                    ] = validation_ev_summary
                    outer_validation_deployment_metrics[
                        "calibrated_drift_risk"
                    ] = outer_risk_apply
            else:
                outer_validation_metrics = {
                    "status": "no_rows_above_deployment_rank_threshold",
                    "validation_rows": int(len(df_policy_outer_validation)),
                    "deployment_rank_threshold": float(deployment_rank_threshold),
                }
        candidate_rows = _build_simple_policy_candidate_rows(
            strategy_id=strategy_id,
            df_top=df_top.copy().reset_index(drop=True),
            paths=all_paths,
            cost_pct=cost_pct,
            best_params=final_params,
            best_size_power=final_size_power,
            base_strategy_threshold=deployment_rank_threshold,
            market_mode=market_mode,
            regime_ae_feature_columns=_infer_regime_ae_source_feature_columns(
                df_policy_all
            ),
            regime_ae_fit_frame=df_policy_all,
        )
        candidate_rows, candidate_risk_apply = _apply_simple_policy_calibrated_drift_risk(
            candidate_rows,
            policy_drift_risk_fit,
            context="simple_policy_candidate_export",
        )
        candidate_rows, uncertainty_ev_summary = _fit_uncertainty_adjusted_ev(
            candidate_rows,
            strategy_id=strategy_id,
        )
        strategy_support_funnel_frames.append(
            _strategy_support_funnel_stage(
                strategy_id,
                "candidate_export_pre_global_rank_rows",
                candidate_rows,
            )
        )
        if not candidate_rows.empty:
            logger.info(
                "[%s] Portfolio candidate export pre-normalization rows=%s "
                "deployment_rank_threshold=%.4f",
                strategy_id,
                len(candidate_rows),
                deployment_rank_threshold,
            )
            simple_policy_candidate_frames.append(candidate_rows)
        if enable_regime_adaptor:
            regime_adaptor_summary = _fit_meta_correctness_regime_adaptor_from_simple_policy(
                data_root=data_root,
                run_id=run_id,
                strategy_id=strategy_id,
                df_policy_all=df_policy_all,
                all_policy_paths=all_policy_paths,
                trade_idx=opt_indices_all[trade_idx],
                final_params=final_params,
                final_size_power=final_size_power,
                cost_pct=cost_pct,
                deployment_rank_threshold=deployment_rank_threshold,
                market_mode=market_mode,
                trade_candidate_oof=candidate_rows,
            )
        else:
            regime_adaptor_summary = {
                "status": "disabled",
                "reason": "simple_policy_regime_adaptor_disabled",
            }
        asset_metrics = build_asset_metrics_from_simulation(
            selected_rows=df_top,
            metrics=deployment_sim_metrics,
            symbol_col="symbol",
            policy_col="strategy_id",
            candidate_rows=df_top,
        )
        weighted_asset_metrics = apply_asset_weights(
            asset_metrics,
            policy_col="strategy_id",
            symbol_col="symbol",
            pnl_col="mean_net_gain",
            sortino_col="sortino",
            tprint_fn=tprint,
        )
        recent_oof_asset_metrics, recent_oof_summary = _build_recent_oof_asset_metrics(
            meta_oof_dir=meta_oof_dir,
            strategy_id=strategy_id,
            deployment_rank_threshold=float(deployment_rank_threshold),
            cost_pct=cost_pct,
            market_mode=market_mode,
        )
        recent_oof_asset_summaries.append(recent_oof_summary)
        if not recent_oof_asset_metrics.empty:
            recent_oof_asset_report_frames.append(recent_oof_asset_metrics.copy())
            weighted_asset_metrics = _merge_recent_oof_asset_metrics(
                weighted_asset_metrics,
                recent_oof_asset_metrics,
                strategy_id=strategy_id,
            )
            logger.info(
                "[%s] Recent OOF asset audit: assets=%s blacklisted=%s "
                "down_weighted=%s source=%s",
                strategy_id,
                int(recent_oof_summary.get("assets", 0) or 0),
                int(recent_oof_summary.get("blacklisted_assets", 0) or 0),
                int(recent_oof_summary.get("down_weighted_assets", 0) or 0),
                recent_oof_summary.get("source_path"),
            )
        if not weighted_asset_metrics.empty:
            cleaned_asset_metrics = weighted_asset_metrics.replace(
                [np.inf, -np.inf], np.nan
            )
            asset_metric_rows = cleaned_asset_metrics.where(
                pd.notna(cleaned_asset_metrics), None
            ).to_dict(orient="records")
        else:
            asset_metric_rows = []
        logger.info(
            "[%s] Final all-data fit best_params=%s best_size_power=%.3f "
            "deployment_rank_threshold=%.4f final_mean_net_trade=%.6f",
            strategy_id,
            final_params,
            final_size_power,
            float(
                deployment_threshold_metrics.get("deployment_rank_threshold", np.nan)
            ),
            float(final_policy_deployment_metrics.get("mean_net_trade", np.nan)),
        )

        strategy_results = {
            "best_params": final_params,
            "best_size_power": float(final_size_power),
            "metrics": {
                "cv_validation_average": validation_metrics_average,
                "final_fit_all": final_fit_metrics,
                "outer_policy_validation": outer_validation_metrics,
            },
            "deployment_threshold_metrics": deployment_threshold_metrics,
            "final_policy_deployment_metrics": final_policy_deployment_metrics,
            "outer_policy_validation_deployment_metrics": outer_validation_deployment_metrics,
            "simple_policy_calibrated_drift_risk": {
                "fit": policy_drift_risk_fit_summary,
                "candidate_export": candidate_risk_apply,
            },
            "uncertainty_adjusted_ev": uncertainty_ev_summary,
            "policy_outer_split": policy_outer_split,
            "asset_metrics": asset_metric_rows,
            "cv_folds": fold_results,
            "final_fit_summary": final_fit_summary,
            "regime_adaptor": regime_adaptor_summary,
            "recent_oof_asset_exclusion_summary": recent_oof_summary,
            "prediction_source": {
                "parquet": meta_oof_sources.get(strategy_id),
                "score_column": "clf",
                "score_normalization": "calibrated_score_and_threshold",
                "deployment_score_column": "calibrated_score",
                "source": _policy_prediction_source_label(
                    meta_oof_sources.get(strategy_id)
                ),
                "requested_precomputed_meta_oof": bool(use_precomputed_meta_oof),
                "uses_precomputed_meta_oof": (
                    _policy_prediction_source_uses_precomputed_meta_oof(
                        meta_oof_sources.get(strategy_id)
                    )
                ),
                "oos_oof_columns_used": [
                    c
                    for c in ["oof_meta_clf", "oof_pred", "oof_p_move", "oof_base_clf"]
                    if c in df.columns
                ],
                "slice_plan_path": str(slice_plan_path),
                **source_validation,
            },
        }

        val_mask_top5 = df_top["rank_pct"].to_numpy() >= 0.95
        if np.any(val_mask_top5):
            mask_idx = np.where(val_mask_top5)[0]
            f_op, f_hi, f_lo, f_cl = all_paths
            diagnostic_metrics = simulate_and_score(
                df_top.iloc[mask_idx].copy(),
                f_op[mask_idx],
                f_hi[mask_idx],
                f_lo[mask_idx],
                f_cl[mask_idx],
                cost_pct=cost_pct,
                size_power=final_size_power,
                **final_params,
            )
            diagnostic_df = _build_top5_validation_diagnostic(
                df_top.iloc[mask_idx].copy(),
                diagnostic_metrics,
            )
            if diagnostic_df is not None and not diagnostic_df.empty:
                daily = (
                    diagnostic_df.set_index("timestamp")["net_gain"]
                    .resample("D")
                    .sum()
                    .pct_change()
                    .replace([np.inf, -np.inf], np.nan)
                    .dropna()
                )
                weekly = (
                    diagnostic_df.set_index("timestamp")["net_gain"]
                    .resample("W")
                    .sum()
                    .pct_change()
                    .replace([np.inf, -np.inf], np.nan)
                    .dropna()
                )
                strategy_top5_daily_weekly.append(
                    {"strategy_id": strategy_id, "daily": daily, "weekly": weekly}
                )

        results_json[strategy_id] = strategy_results
        oos_results_json["strategies"][strategy_id] = {
            "best_params": final_params,
            "best_size_power": float(final_size_power),
            "validation_metrics": validation_metrics_average,
            "outer_policy_validation_metrics": outer_validation_metrics,
            "cv_folds": fold_results,
            "final_fit_metrics": final_fit_metrics,
            "final_fit_summary": final_fit_summary,
            "deployment_threshold_metrics": deployment_threshold_metrics,
            "final_policy_deployment_metrics": final_policy_deployment_metrics,
            "outer_policy_validation_deployment_metrics": outer_validation_deployment_metrics,
            "simple_policy_calibrated_drift_risk": {
                "fit": policy_drift_risk_fit_summary,
                "candidate_export": candidate_risk_apply,
            },
            "uncertainty_adjusted_ev": uncertainty_ev_summary,
            "asset_metrics": asset_metric_rows,
            "recent_oof_asset_exclusion_summary": recent_oof_summary,
            "regime_adaptor": regime_adaptor_summary,
            "validation_rows_stage_b_avg": float(
                np.mean([len(fold) for fold in folds]) if folds else 0.0
            ),
            "optimisation_rows_stage_b_avg": float(
                np.mean([n - len(fold) for fold in folds]) if folds else 0.0
            ),
            "validation_rows_top15_avg": float(
                np.mean([len(fold) for fold in folds]) if folds else 0.0
            ),
            "optimisation_rows_top15_avg": float(
                np.mean([n - len(fold) for fold in folds]) if folds else 0.0
            ),
            "full_policy_rows": int(n_policy),
            "policy_optimisation_rows": int(len(df_policy_fit)),
            "policy_outer_validation_rows": int(len(df_policy_outer_validation)),
            "stage_b_policy_rows": int(n),
            "policy_outer_split": policy_outer_split,
            "source_validation": strategy_results["prediction_source"],
        }

    ic_rows = []
    for item in strategy_top5_daily_weekly:
        daily = item["daily"]
        weekly = item["weekly"]
        idx = daily.index.intersection(weekly.index)
        ic = float(daily.loc[idx].corr(weekly.loc[idx])) if len(idx) >= 3 else np.nan
        ic_rows.append(
            {
                "strategy_id": item["strategy_id"],
                "daily_weight": 0.3,
                "weekly_weight": 0.7,
                "ic_daily_vs_weekly_pct_change_top5": ic,
                "n_overlap": int(len(idx)),
            }
        )
    results_json["__cross_strategy_diagnostics__"] = {"ic_table": ic_rows}
    recent_oof_report_dir = output_run_root / "simple_policy_optimiser"
    recent_oof_report_dir.mkdir(parents=True, exist_ok=True)
    recent_oof_summary_payload = {
        "enabled": bool(RECENT_OOF_ASSET_EXCLUSION_ENABLE),
        "lookback_months": int(RECENT_OOF_LOOKBACK_MONTHS),
        "train_recent_months": int(RECENT_OOF_TRAIN_RECENT_MONTHS),
        "decision_months": int(RECENT_OOF_DECISION_MONTHS),
        "decision_scope": "full_lookback",
        "recent_stress_weeks": int(RECENT_OOF_RECENT_STRESS_WEEKS),
        "min_top_rows": int(RECENT_OOF_MIN_TOP_ROWS),
        "min_total_rows": int(RECENT_OOF_MIN_TOTAL_ROWS),
        "lcb_z": float(RECENT_OOF_LCB_Z),
        "blacklist_lcb_bps": float(RECENT_OOF_BLACKLIST_LCB_BPS),
        "blacklist_bps_weighted_hit_max": float(
            RECENT_OOF_BLACKLIST_BPS_WEIGHTED_HIT_MAX
        ),
        "downweight_bps_weighted_hit_max": float(
            RECENT_OOF_DOWNWEIGHT_BPS_WEIGHTED_HIT_MAX
        ),
        "min_rank_pct": float(RECENT_OOF_MIN_RANK_PCT),
        "strategies": recent_oof_asset_summaries,
    }
    if recent_oof_asset_report_frames:
        recent_oof_report = pd.concat(
            recent_oof_asset_report_frames,
            ignore_index=True,
            sort=False,
        )
        recent_oof_report_path = (
            recent_oof_report_dir / "recent_oof_asset_exclusion_report.csv"
        )
        recent_oof_report.to_csv(recent_oof_report_path, index=False)
        recent_oof_summary_payload["report_path"] = str(recent_oof_report_path)
    recent_oof_summary_path = (
        recent_oof_report_dir / "recent_oof_asset_exclusion_summary.json"
    )
    _write_text_with_mode_alias(
        recent_oof_summary_path,
        json.dumps(_json_safe(recent_oof_summary_payload), indent=2),
        market_mode,
    )
    results_json["__recent_oof_asset_exclusion__"] = recent_oof_summary_payload
    oos_results_json["recent_oof_asset_exclusion"] = recent_oof_summary_payload

    output_path = output_run_root / "policy_optimisation.json"
    results_text = json.dumps(_json_safe(results_json), indent=4)
    _write_text_with_mode_alias(output_path, results_text, market_mode)
    logger.info(f"Saved policy optimisation results to {output_path}")
    oos_output_path = output_run_root / "policy_optimisation_oos_metrics.json"
    oos_text = json.dumps(_json_safe(oos_results_json), indent=4)
    _write_text_with_mode_alias(oos_output_path, oos_text, market_mode)
    logger.info(f"Saved OOS policy metrics to {oos_output_path}")

    auction_reference_table = _finalise_simple_policy_candidates(
        simple_policy_candidate_frames,
        rank_floor=0.0,
    )
    candidate_table = _finalise_simple_policy_candidates(simple_policy_candidate_frames)
    strategy_support_funnel_frames.extend(
        _strategy_support_funnel_table_stages(
            "broad_candidate_export_rows",
            auction_reference_table,
        )
    )
    strategy_support_funnel_frames.extend(
        _strategy_support_funnel_table_stages(
            "global_export_rank_floor_rows",
            candidate_table,
        )
    )
    candidate_path = (
        output_run_root
        / "simple_policy_optimiser"
        / "simple_policy_candidates.parquet"
    )
    broad_candidate_path = (
        candidate_path.parent / "simple_policy_candidates_broad.parquet"
    )
    if not auction_reference_table.empty:
        candidate_path.parent.mkdir(parents=True, exist_ok=True)
        auction_reference_table.to_parquet(broad_candidate_path, index=False)
        broad_candidate_metadata_path = (
            candidate_path.parent / "simple_policy_candidates_broad_metadata.json"
        )
        _write_simple_policy_candidate_metadata(
            auction_reference_table,
            output_path=broad_candidate_metadata_path,
        )
        logger.info(
            "Saved broad simple policy candidate table to %s rows=%s metadata=%s",
            broad_candidate_path,
            len(auction_reference_table),
            broad_candidate_metadata_path,
        )
    if not candidate_table.empty:
        try:
            _validate_delayed_entry_execution_coverage(
                candidate_table,
                artifact_label=str(candidate_path),
            )
        except RuntimeError as exc:
            _write_policy_export_failure_diagnostics(
                candidate_table,
                candidate_path.parent,
                run_id=run_id,
                market_mode=market_mode,
            )
            _write_policy_export_invalid_marker(
                candidate_path.parent,
                run_id=run_id,
                market_mode=market_mode,
                reason=exc,
            )
            raise
        _clear_policy_export_invalid_marker(candidate_path.parent)

    deployment_payload = _build_deployment_payload(
        run_id=run_id,
        oos_results_json=oos_results_json,
        available_strategy_ids=_available_strategy_ids_from_meta_oof(meta_oof_dir),
        market_mode=market_mode,
    )
    deployment_payload["market_mode"] = market_mode
    _apply_local_candidate_hit_rate_guard(
        deployment_payload,
        auction_reference_table,
        candidate_path=candidate_path,
    )
    _refresh_deployment_reconciliation(deployment_payload)
    policy_params_dir = output_run_root / "policy_params"
    policy_params_dir.mkdir(parents=True, exist_ok=True)
    deployment_text = json.dumps(_json_safe(deployment_payload), indent=2)
    deployment_paths = [
        policy_params_dir / "strategy_for_inference.json",
        output_run_root / "strategy_for_inference.json",
        policy_params_dir / "best_policy_params.json",
        output_run_root / "best_policy_params.json",
        output_run_root
        / "simple_policy_optimiser"
        / "deployment"
        / "best_policy_params.json",
    ]
    for deployment_path in deployment_paths:
        _write_text_with_mode_alias(deployment_path, deployment_text, market_mode)
        logger.info(f"Saved deployment policy contract to {deployment_path}")
    portfolio_policy_path = policy_params_dir / "portfolio_policy_config.json"
    _write_text_with_mode_alias(
        portfolio_policy_path,
        json.dumps(_json_safe(_build_portfolio_policy_config_payload()), indent=2),
        market_mode,
    )
    logger.info(f"Saved portfolio policy config to {portfolio_policy_path}")

    if not candidate_table.empty:
        candidate_path.parent.mkdir(parents=True, exist_ok=True)
        candidate_table.to_parquet(candidate_path, index=False)
        candidate_metadata_path = (
            candidate_path.parent / "simple_policy_candidates_metadata.json"
        )
        _write_simple_policy_candidate_metadata(
            candidate_table,
            output_path=candidate_metadata_path,
        )
        logger.info("Saved simple policy candidate metadata to %s", candidate_metadata_path)
        auction_ref_path = persist_auction_rank_reference(
            auction_reference_table,
            data_root=data_root,
            run_id=run_id,
            market_mode=market_mode,
            output_dir=rank_reference_output_dir,
        )
        logger.info(
            "Saved simple policy portfolio candidate table to %s rows=%s auction_ref=%s",
            candidate_path,
            len(candidate_table),
            auction_ref_path,
        )
        _write_delay_rejection_reports(
            candidate_table,
            output_dir=candidate_path.parent,
        )
        _write_rank_threshold_band_reports(
            candidate_table,
            output_dir=candidate_path.parent,
        )
        try:
            ts_for_drift = pd.to_datetime(
                candidate_table.get("timestamp"), utc=True, errors="coerce"
            )
            label_maturity_cutoff_ts = (
                ts_for_drift.max()
                if len(ts_for_drift.dropna())
                else pd.Timestamp.now(tz="UTC")
            )
            drift_benchmark_summary = write_policy_drift_benchmarks(
                candidate_table,
                output_dir=output_run_root / "drift_benchmarks",
                provenance={
                    "asof_ts": pd.Timestamp.now(tz="UTC"),
                    "label_maturity_cutoff_ts": label_maturity_cutoff_ts,
                    "model_run_id": str(run_id),
                    "policy_run_id": str(run_id),
                    "policy_version": str(
                        deployment_payload.get("policy_version")
                        or deployment_payload.get("version")
                        or ""
                    ),
                    "market_mode": market_mode,
                },
            )
            logger.info(
                "Saved drift monitoring benchmarks under %s rows=%s",
                output_run_root / "drift_benchmarks",
                drift_benchmark_summary,
            )
        except Exception as exc:
            logger.warning("Failed to write drift monitoring benchmarks: %s", exc)
        logger.info(
            "Saved delayed-entry price move breakdown, adverse rejection "
            "simulations, and rank-threshold band reports under %s",
            candidate_path.parent,
        )
        _assert_deployment_has_selected_strategies(
            deployment_payload,
            candidate_path=candidate_path,
        )
        deployed_strategy_ids = _deployment_selected_strategy_ids(
            deployment_payload
        )
        replay_candidate_table = _filter_candidates_to_deployment_strategies(
            auction_reference_table,
            deployed_strategy_ids,
            deployment_payload=deployment_payload,
        )
        strategy_support_funnel_frames.extend(
            _strategy_support_funnel_table_stages(
                "deployable_strategy_threshold_rows",
                replay_candidate_table,
            )
        )
        _write_strategy_support_funnel_report(
            strategy_support_funnel_frames,
            output_dir=candidate_path.parent,
            market_mode=market_mode,
        )
        if replay_candidate_table.empty:
            raise RuntimeError(
                "No simple policy candidate rows remain after filtering to "
                f"deployed strategies: strategies={deployed_strategy_ids}"
            )
        candidate_table, replay_candidate_table, threshold_selector_report = (
            _select_deployment_threshold_by_portfolio_replay(
                deployment_payload,
                candidate_table,
                replay_candidate_table,
                output_dir=candidate_path.parent,
                market_mode=market_mode,
            )
        )
        if threshold_selector_report.get("updated"):
            candidate_table.to_parquet(candidate_path, index=False)
            _write_simple_policy_candidate_metadata(
                candidate_table,
                output_path=candidate_metadata_path,
            )
            _rewrite_deployment_payload_artifacts(
                deployment_payload,
                deployment_paths=deployment_paths,
                market_mode=market_mode,
            )
        replay_candidate_path = (
            candidate_path.parent / "simple_policy_candidates_deployable.parquet"
        )
        replay_candidate_table.to_parquet(replay_candidate_path, index=False)
        logger.info(
            "Saved deployable simple policy candidate table to %s rows=%s "
            "strategies=%s",
            replay_candidate_path,
            len(replay_candidate_table),
            len(deployed_strategy_ids),
        )
        _write_rank_threshold_band_reports(
            replay_candidate_table,
            output_dir=candidate_path.parent / "deployable_rank_threshold_bands",
        )
        logger.info(
            "Saved deployable-only rank-threshold band reports under %s",
            candidate_path.parent / "deployable_rank_threshold_bands",
        )
        if not _env_flag("EPM_SIMPLE_POLICY_RUN_PORTFOLIO_REPLAY", True):
            logger.info(
                "Skipping portfolio policy replay because "
                "EPM_SIMPLE_POLICY_RUN_PORTFOLIO_REPLAY is disabled."
            )
            return
        try:
            from extreme_price_movements.portfolio_policy_replay import (
                run_portfolio_policy_replay,
            )

            replay_report = run_portfolio_policy_replay(
                data_root=data_root,
                run_id=run_id,
                market_mode=market_mode,
                candidate_path=replay_candidate_path,
                output_dir=output_run_root / "portfolio_policy_replay",
                persist_live_artifacts=output_run_root == run_root,
            )
            optimized_portfolio_path = (
                output_run_root
                / "portfolio_policy_replay"
                / "optimized_portfolio_policy_config.json"
                if output_run_root != run_root
                else Path(data_root)
                / "artifacts"
                / run_id
                / "policy_params"
                / "optimized_portfolio_policy_config.json"
            )
            optimized_portfolio_payload: Dict[str, Any] = {}
            if optimized_portfolio_path.exists():
                optimized_portfolio_payload = json.loads(
                    optimized_portfolio_path.read_text(encoding="utf-8")
                )
            if not deployed_strategy_ids:
                deployed_strategy_ids = sorted(
                    {
                        str(sid)
                        for sid in candidate_table["strategy_id"].dropna().unique()
                        if str(sid).strip()
                    }
                )
            if optimized_portfolio_payload:
                optimized_portfolio_payload = _apply_deployment_strategy_contract(
                    optimized_portfolio_payload,
                    deployed_strategy_ids,
                )
                optimized_portfolio_path.write_text(
                    json.dumps(_json_safe(optimized_portfolio_payload), indent=2),
                    encoding="utf-8",
                )
                policy_params_optimized_path = (
                    policy_params_dir / "optimized_portfolio_policy_config.json"
                )
                if policy_params_optimized_path != optimized_portfolio_path:
                    _write_text_with_mode_alias(
                        policy_params_optimized_path,
                        json.dumps(
                            _json_safe(optimized_portfolio_payload), indent=2
                        ),
                        market_mode,
                    )
                    logger.info(
                        "Mirrored optimized live portfolio policy config to %s",
                        policy_params_optimized_path,
                    )
                logger.info(
                    "Updated live portfolio policy strategy contract to deployed "
                    "strategy set: %s strategies",
                    len(deployed_strategy_ids),
                )
            if output_run_root == run_root:
                _write_training_live_parity_contract(
                    data_root=data_root,
                    run_id=run_id,
                    market_mode=market_mode,
                    strategy_ids=deployed_strategy_ids,
                    deployment_payload=deployment_payload,
                    portfolio_payload=optimized_portfolio_payload,
                )
            else:
                logger.info(
                    "Skipping live training-parity contract persistence because "
                    "EPM_SIMPLE_POLICY_OUTPUT_RUN_ROOT is set: %s",
                    output_run_root,
                )
            logger.info(
                "Portfolio policy replay completed: objective=%.6f trades=%s accepted=%s",
                float(
                    replay_report.get("global_auction_metrics", {}).get(
                        "objective", np.nan
                    )
                ),
                replay_report.get("global_auction_metrics", {}).get("trade_count"),
                replay_report.get("walk_forward", {}).get("accepted"),
            )
        except Exception as exc:
            logger.exception(
                "Portfolio policy replay failed after candidate export: %s", exc
            )
            raise
    else:
        raise RuntimeError(
            "No simple policy candidate rows available for portfolio replay."
        )


def _policy_params_from_deployment_strategy(
    strategy: Dict[str, Any],
    selection_rules: Dict[str, Any],
) -> Tuple[Dict[str, Any], float, float]:
    param_keys = (
        "sl_mult",
        "trailing_activation_mult",
        "trailing_power",
        "trailing_squash_divisor",
        "giveback_beta",
        "atr_power",
        "atr_multiplier",
        "hard_tp_abs_pct",
        "exit_pressure_enabled",
        "exit_pressure_alpha",
        "exit_pressure_beta",
        "exit_pressure_delta",
        "exit_pressure_kappa",
        "exit_pressure_psi",
        "exit_pressure_omega",
        "exit_pressure_min_multiplier",
        "redeploy_scale_bps",
        "target_holding_hours",
        "churn_penalty_bps",
        "median_barrier_frac",
        "policy_median_barrier_frac",
        "capital_protect_mfe_mult",
        "capital_protect_regression_frac",
        "adverse_exit_enabled",
        "adverse_exit_min_mae_atr",
        "adverse_exit_min_speed",
        "adverse_exit_theta_quantile",
        "adverse_exit_theta",
        "adverse_exit_alpha",
        "adverse_exit_beta",
        "adverse_exit_delta",
        "adverse_exit_fast_bars",
        "adverse_exit_max_mfe_atr",
    )
    params = {k: strategy[k] for k in param_keys if k in strategy}
    max_concurrent = strategy.get(
        "max_concurrent_trades", selection_rules.get("max_concurrent_per_strategy")
    )
    if max_concurrent is not None:
        params["max_concurrent_trades"] = int(max(1, float(max_concurrent)))
    max_per_asset = strategy.get(
        "max_concurrent_per_asset", selection_rules.get("max_concurrent_per_asset")
    )
    if max_per_asset is not None:
        params["max_concurrent_per_asset"] = int(max(1, float(max_per_asset)))
    size_power = float(strategy.get("best_size_power", 1.0))
    threshold = float(strategy.get("deployment_rank_threshold", 1.0))
    return params, size_power, threshold


def run_regime_adaptor_only_from_simple_policy(
    data_root: str,
    run_id: Optional[str],
    *,
    cost_pct: float = DEFAULT_POLICY_PER_SIDE_COST_PCT,
    strategy_ids: Optional[Sequence[str]] = None,
    market_mode: Optional[str] = None,
) -> Dict[str, Any]:
    market_mode = _normalise_market_mode(market_mode)
    data_root = _resolve_market_data_root(data_root, market_mode)
    artifacts_root = Path(data_root) / "artifacts"
    if run_id is None:
        candidates = [p for p in artifacts_root.iterdir() if p.is_dir()]
        if not candidates:
            logger.error(f"No artifact runs found under {artifacts_root}")
            return {}
        run_id = max(candidates, key=lambda p: p.stat().st_mtime).name
        logger.info(f"No run_id supplied; using latest artifact run {run_id}")
    run_root = Path(data_root) / "artifacts" / str(run_id)
    deployment_path = resolve_mode_file(
        run_root / "simple_policy_optimiser" / "deployment" / "best_policy_params.json",
        market_mode,
    )
    if not deployment_path.exists():
        deployment_path = resolve_mode_file(
            run_root / "policy_params" / "best_policy_params.json",
            market_mode,
        )
    if not deployment_path.exists():
        logger.error("No simple-policy deployment contract found under %s", run_root)
        return {}

    payload = json.loads(deployment_path.read_text())
    selection_rules = payload.get("selection_rules", {})
    allow = set(_expand_strategy_id_allowlist(strategy_ids or []))
    strategies = [
        s
        for s in payload.get("strategies", [])
        if bool(s.get("selected", True))
        and (not allow or str(s.get("strategy_id")) in allow)
    ]
    if not strategies:
        logger.warning(
            "No selected simple-policy strategies found in %s", deployment_path
        )
        return {}

    from extreme_price_movements.inference.parity import calibrated_score_and_threshold
    from extreme_price_movements.simple_position_sizer import load_calibration_curves

    slice_plan_path = run_root / "slices" / "slice_plan.json"
    stage_view, stage_name = _load_policy_stage_view(slice_plan_path)
    source_validation = _load_slice_plan_source_validation(slice_plan_path)
    meta_oof_dir = run_root / "meta_oof"
    ds = _make_policy_replay_store(data_root, market_mode)
    calibration_data = load_calibration_curves(data_root, str(run_id))
    summaries: Dict[str, Any] = {
        "generated_by": "simple_policy_regime_adaptor_only",
        "market_mode": market_mode,
        "run_id": str(run_id),
        "deployment_policy_path": str(deployment_path),
        "stage": stage_name,
        "source_validation": source_validation,
        "strategies": {},
    }

    for strategy in strategies:
        strategy_id = str(strategy.get("strategy_id"))
        candidates = _recent_oof_path_candidates(meta_oof_dir, strategy_id)
        route_paths = [
            path
            for path in candidates
            if path.exists() and mr_tf_route_from_path(path) in {"mr", "tf"}
        ]
        meta_path = next(
            (
                path
                for path in candidates
                if path.exists() and mr_tf_route_from_path(path) not in {"mr", "tf"}
            ),
            None,
        )
        if meta_path is None:
            logger.warning("[%s] Missing canonical meta OOF parquet", strategy_id)
            continue
        df = pd.read_parquet(meta_path)
        df = _filter_rows_to_stage_view(df, stage_view)
        if df.empty:
            logger.warning("[%s] No rows after policy slice filter.", strategy_id)
            continue
        df, route_overlay = _overlay_meta_oof_route_paths(
            df,
            route_paths,
            market_mode=market_mode,
            stage_view=stage_view,
        )
        if route_overlay:
            logger.info(
                "[%s] Applied MR/TF regime-adaptor-only OOF overlays: %s",
                strategy_id,
                route_overlay,
            )
        df = _ensure_regime_prediction_context(
            df,
            data_root=data_root,
            run_id=str(run_id),
            strategy_id=strategy_id,
            stage_view=stage_view,
        )
        if "clf" not in df.columns and "oof_p_tp" in df.columns:
            df["clf"] = df["oof_p_tp"]
        elif "clf" not in df.columns and "oof_pred" in df.columns:
            df["clf"] = df["oof_pred"]
        if "clf" not in df.columns:
            logger.warning("[%s] Missing meta score column; skipped.", strategy_id)
            continue
        df["raw_meta_prediction"] = pd.to_numeric(df["clf"], errors="coerce")
        df["calibrated_score"] = df["raw_meta_prediction"].map(
            lambda raw_score: (
                calibrated_score_and_threshold(
                    raw_score=float(raw_score),
                    strategy_id=strategy_id,
                    calibration_data=calibration_data,
                    default_threshold=1.0,
                )[0]
                if pd.notna(raw_score)
                else np.nan
            )
        )
        df["rank_pct"] = df["calibrated_score"].rank(method="max", pct=True)
        df["strategy_id"] = strategy_id
        if "side" not in df.columns:
            df["side"] = -1 if strategy_id.startswith("short") else 1
        df_policy_all = df.dropna(
            subset=["timestamp", "symbol", "rank_pct", "calibrated_score"]
        ).copy()
        df_policy_all["market_mode"] = market_mode
        df_policy_all = df_policy_all.sort_values("timestamp").reset_index(drop=True)
        if len(df_policy_all) < 50:
            logger.warning(
                "[%s] Too few policy rows: %s", strategy_id, len(df_policy_all)
            )
            continue
        final_params, final_size_power, deployment_rank_threshold = (
            _policy_params_from_deployment_strategy(strategy, selection_rules)
        )
        trade_idx = np.flatnonzero(
            df_policy_all["rank_pct"].to_numpy(dtype=np.float32)
            >= float(deployment_rank_threshold)
        )
        if len(trade_idx) < 10:
            logger.warning(
                "[%s] Too few rows above saved deployment threshold %.4f: %s",
                strategy_id,
                deployment_rank_threshold,
                len(trade_idx),
            )
            continue
        logger.info(
            "[%s] Running regime adaptor only from saved simple policy: rows=%s "
            "rank_threshold=%.4f candidates=%s params_hash=%s",
            strategy_id,
            len(df_policy_all),
            deployment_rank_threshold,
            len(trade_idx),
            strategy.get("params_hash", ""),
        )
        all_policy_paths = _fetch_policy_paths(df_policy_all, ds)
        df_policy_all, all_policy_paths = _apply_delayed_entry_execution_model(
            df_policy_all,
            all_policy_paths,
            data_root=data_root,
            market_mode=market_mode,
        )
        candidate_rows = _build_simple_policy_candidate_rows(
            strategy_id=strategy_id,
            df_top=df_policy_all.iloc[trade_idx].copy().reset_index(drop=True),
            paths=_path_take(all_policy_paths, trade_idx),
            cost_pct=cost_pct,
            best_params=final_params,
            best_size_power=final_size_power,
            base_strategy_threshold=deployment_rank_threshold,
            market_mode=market_mode,
            regime_ae_feature_columns=_infer_regime_ae_source_feature_columns(
                df_policy_all
            ),
            regime_ae_fit_frame=df_policy_all,
        )
        summary = _fit_meta_correctness_regime_adaptor_from_simple_policy(
            data_root=data_root,
            run_id=str(run_id),
            strategy_id=strategy_id,
            df_policy_all=df_policy_all,
            all_policy_paths=all_policy_paths,
            trade_idx=trade_idx,
            final_params=final_params,
            final_size_power=final_size_power,
            cost_pct=cost_pct,
            deployment_rank_threshold=deployment_rank_threshold,
            market_mode=market_mode,
            trade_candidate_oof=candidate_rows,
        )
        summaries["strategies"][strategy_id] = {
            "regime_adaptor": summary,
            "policy_rows": int(len(df_policy_all)),
            "threshold_candidate_rows": int(len(trade_idx)),
            "deployment_rank_threshold": float(deployment_rank_threshold),
            "policy_params": _json_safe(final_params),
            "best_size_power": float(final_size_power),
        }

    out_path = run_root / "simple_policy_optimiser" / "regime_adaptor_only_summary.json"
    _write_text_with_mode_alias(
        out_path, json.dumps(_json_safe(summaries), indent=2), market_mode
    )
    logger.info("Saved regime-adaptor-only summary to %s", out_path)
    return summaries


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--data_root", type=str, default="/Users/remyroche/Documents/Ares/data"
    )
    parser.add_argument("--run_id", type=str, default=None)
    parser.add_argument(
        "--market-mode",
        choices=["spot", "perps"],
        default="spot",
        help="Market mode for data/artifact files (default: spot).",
    )
    parser.add_argument(
        "--perps", action="store_true", help="Alias for --market-mode perps"
    )
    parser.add_argument("--max-strategies", type=int, default=None)
    parser.add_argument("--n-trials", type=int, default=None)
    parser.add_argument("--strategy-ids", type=str, default="")
    parser.add_argument("--regime-only", action="store_true")
    parser.add_argument(
        "--round-trip-cost-pct",
        type=float,
        default=DEFAULT_POLICY_ROUND_TRIP_COST_PCT,
        help=(
            "All-in round-trip execution cost used by policy optimisation. "
            "Default is 0.002 for 0.2%%."
        ),
    )
    parser.add_argument(
        "--no-regime-adaptor",
        action="store_true",
        help="Skip fitting simple-policy regime adaptor artifacts.",
    )
    args = parser.parse_args()

    cli_strategy_ids = [s.strip() for s in args.strategy_ids.split(",") if s.strip()]
    cli_market_mode = _normalise_market_mode(
        "perps" if args.perps else args.market_mode
    )
    if args.regime_only:
        run_regime_adaptor_only_from_simple_policy(
            args.data_root,
            args.run_id,
            cost_pct=float(args.round_trip_cost_pct) / 2.0,
            strategy_ids=cli_strategy_ids,
            market_mode=cli_market_mode,
        )
    else:
        run_simple_policy_optimisation(
            args.data_root,
            args.run_id,
            cost_pct=float(args.round_trip_cost_pct) / 2.0,
            max_strategies=args.max_strategies,
            n_trials=args.n_trials,
            strategy_ids=cli_strategy_ids,
            market_mode=cli_market_mode,
            enable_regime_adaptor=False if args.no_regime_adaptor else None,
        )
